package akogen.fabric.v6;
import com.google.gson.*;import java.util.*;import java.security.*;import java.io.*;
/** Only bounded cosmetic IDs and animation phase are exchanged. Incoming data is never executable. */
public final class SyncCodec {
 public static final class State {public String catalog,epoch;public int[] ids;public double phase;public boolean clear;public long timestamp;}
 public static String hash(byte[] bytes)throws Exception{byte[] value=MessageDigest.getInstance("SHA-256").digest(bytes);char[] out=new char[value.length*2];final String hex="0123456789abcdef";for(int i=0;i<value.length;i++){int v=value[i]&255;out[i*2]=hex.charAt(v>>>4);out[i*2+1]=hex.charAt(v&15);}return new String(out);}
 public static String topic(UUID uuid)throws Exception{return "akogen/beta/c1/"+hash(("akogen-cosmetics-1:"+uuid.toString()).getBytes("UTF-8")).substring(0,32);}
 public static byte[] encode(String catalog,String epoch,int[] ids,double phase,boolean clear)throws Exception{if(ids.length>12||!Double.isFinite(phase))throw new IOException("Invalid cosmetic state");JsonObject o=new JsonObject();o.addProperty("v",1);o.addProperty("c",catalog);o.addProperty("s",epoch);o.addProperty("t",System.currentTimeMillis());o.addProperty("a",phase);o.addProperty("x",clear);JsonArray a=new JsonArray();for(int id:ids)a.add(id);o.add("e",a);byte[] bytes=o.toString().getBytes("UTF-8");if(bytes.length>2048)throw new IOException("Cosmetic packet too large");return bytes;}
 public static State decode(byte[] bytes,String catalog)throws Exception{if(bytes==null||bytes.length>2048||bytes.length<2)throw new IOException("Cosmetic packet exceeds limit");String json=new String(bytes,"UTF-8");int depth=0;boolean quoted=false,escaped=false;for(int n=0;n<json.length();n++){char ch=json.charAt(n);if(quoted){if(escaped)escaped=false;else if(ch==92)escaped=true;else if(ch==34)quoted=false;}else if(ch==34)quoted=true;else if(ch==123||ch==91){if(++depth>2)throw new IOException("Nested cosmetic packet rejected");}else if(ch==125||ch==93){if(--depth<0)throw new IOException("Invalid packet nesting");}}if(depth!=0||quoted)throw new IOException("Unterminated cosmetic packet");JsonObject o=new JsonParser().parse(json).getAsJsonObject();if(o.get("v").getAsInt()!=1||!catalog.equals(o.get("c").getAsString()))throw new IOException("Different cosmetic version");State s=new State();s.catalog=catalog;s.epoch=o.get("s").getAsString();if(!s.epoch.matches("[0-9a-f]{32}"))throw new IOException("Invalid session");s.timestamp=o.get("t").getAsLong();if(Math.abs(System.currentTimeMillis()-s.timestamp)>300000)throw new IOException("Stale cosmetic packet");s.phase=o.get("a").getAsDouble();if(!Double.isFinite(s.phase)||s.phase<0||s.phase>31536000)throw new IOException("Invalid animation phase");s.clear=o.get("x").getAsBoolean();JsonArray a=o.getAsJsonArray("e");if(a.size()>12)throw new IOException("Too many cosmetics");s.ids=new int[a.size()];Set<Integer> unique=new HashSet<Integer>();for(int n=0;n<a.size();n++){double value=a.get(n).getAsDouble();if(value!=Math.rint(value)||value<0||value>10000||!unique.add((int)value))throw new IOException("Invalid cosmetic ID");s.ids[n]=(int)value;}return s;}
}
